const NU = { mode: 'head', d: null, ws: '', w: '', tab: 'week', cm: null, t: {}, root: null, api: null, at: 0, busy: 0 };
const NU_DN = ['א׳', 'ב׳', 'ג׳', 'ד׳', 'ה׳', 'ו׳', 'שבת'], NU_MN = ['ינואר', 'פברואר', 'מרץ', 'אפריל', 'מאי', 'יוני', 'יולי', 'אוגוסט', 'ספטמבר', 'אוקטובר', 'נובמבר', 'דצמבר'];
