const nuEsc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
function nuToast(t) { if (typeof toast === 'function') return toast(t); const e = document.createElement('div'); e.textContent = t; e.style.cssText = 'position:fixed;bottom:18px;left:50%;transform:translateX(-50%);background:#0C2A35;color:#fff;padding:8px 16px;border-radius:10px;z-index:400;font-weight:600'; document.body.appendChild(e); setTimeout(() => e.remove(), 2400); }
const nuSure = {};
function nuOnce(k, msg) { if (nuSure[k] && Date.now() - nuSure[k] < 6000) { nuSure[k] = 0; return true; } nuSure[k] = Date.now(); nuToast(msg); return false; }
const nuF2 = n => (n < 10 ? '0' : '') + n, nuIso = d => d.getFullYear() + '-' + nuF2(d.getMonth() + 1) + '-' + nuF2(d.getDate()), nuFm = d => d.getDate() + '.' + (d.getMonth() + 1);
const nuDate = s => { const p = String(s).split('-'); return new Date(+p[0], +p[1] - 1, +p[2]); };
const nuFmIso = s => { const p = String(s).split('-'); return +p[2] + '.' + +p[1]; };
const nuAdd = (d, n) => new Date(d.getFullYear(), d.getMonth(), d.getDate() + n);
const nuSun = d => nuAdd(d, -d.getDay());
const nuNextWs = () => nuIso(nuAdd(nuSun(new Date()), 7));
const nuDof = i => nuAdd(nuDate(NU.ws), i);
const nuWe = d => d >= 5;
// who is looking: the manager's view (a head nurse, the owner, a viewer) or a nurse; edit only for the wing's head and the owner
const nuMgr = () => NU.mode === 'head';
const nuEd = () => NU.mode === 'head' && !!(NU.d && NU.d.edit);
const nuMe = () => NU.mode === 'nurse' && NU.d ? NU.d.me.id : '';
const nuW = () => NU.d.wk, nuSet = () => NU.d.cfg, nuStf = () => NU.d.staff || [];
const nuBy = id => nuStf().find(p => p.id === id) || { n: '?', q: [] };
const nuCan = (p, q) => (p.q || []).indexOf(q) >= 0;
const nuBase = v => String(v || '').replace('*', '');
// ---------- the grid model
function nuVacOn(id, d) { const x = nuIso(nuDof(d)); return (NU.d.vac || []).some(v => v.w === id && v.st === 'ok' && v.from <= x && v.to >= x); }
function nuCell(id, d) { const P = nuBy(id); if (P.leave) return 'L:' + P.leave; if (nuVacOn(id, d)) return 'V'; return (nuW().grid[id] || [])[d] || ''; }
function nuPut(id, d, v) { const g = nuW().grid; (g[id] = g[id] || ['', '', '', '', '', '', ''])[d] = v; }
// shifts in the shown week by job size: 5, "3/4" (alternating: the first on even weeks) or "3-4" (between, by need; the builder aims high, the check accepts both)
function nuQr(p) { if (p.leave) return [0, 0]; const v = String((nuSet().quota || {})[p.pct] == null ? Math.round((+p.pct || 0) / 20) : nuSet().quota[p.pct]);
  let m = v.match(/^(\d)\/(\d)$/); if (m) { const wk = Math.floor((nuDate(NU.ws) - new Date(2026, 0, 4)) / 6048e5), x = +(Math.abs(wk) % 2 ? m[2] : m[1]); return [x, x]; }
  m = v.match(/^(\d)-(\d)$/); if (m) return [+m[1], +m[2]]; return [+v || 0, +v || 0]; }
function nuQuota(p) { return nuQr(p)[1]; }
function nuWorked(id) { let n = 0; for (let d = 0; d < 7; d++) if (NU_SH.indexOf(nuBase(nuCell(id, d))) >= 0) n++; return n; }
function nuNeed(d, s, g) { return ((nuSet()[nuWe(d) ? 'minWe' : 'min'] || {})[s] || {})[g] || 0; }
function nuHave(d, s, g) { return nuStf().filter(p => p.prof === g && nuBase(nuCell(p.id, d)) === s).length; }
function nuBlocks(id) { return ((nuW().req || {})[id] || { b: [] }).b || []; }
function nuHit(id, d, s) { return nuBlocks(id).some(b => (b.d === d && (b.s === 'all' || b.s === s)) || (b.nb && b.d === d + 1 && s === 'N')); }
