  if (nuHit(p.id, d, v)) return 'bad'; if (nuSet().noBN && d > 0 && nuBase(nuCell(p.id, d - 1)) === 'N' && v !== 'N') return 'bad'; return ''; }
function nuIssues() { const L = [], W = nuW(), P = nuStf();
  for (let d = 0; d < 7; d++) NU_SH.forEach(s => ['rn', 'aid', 'stu'].forEach(g => { const n = nuNeed(d, s, g), h = nuHave(d, s, g); if (h < n) L.push(['r', `${NU_DN[d]} ${nuFm(nuDof(d))} ${NU_SHN[s]}: ${h}/${n} ${g === 'rn' ? 'אחיות' : g === 'aid' ? 'כוח עזר' : 'סטודנטים'}`]); }));
  for (let d = 0; d < 7; d++) NU_SH.forEach(s => { if (nuHave(d, s, 'rn') && !P.some(p => nuCell(p.id, d) === s + '*')) L.push(['a', `${NU_DN[d]} ${NU_SHN[s]}: אין אחראית משמרת`]); });
  if (nuSet().oncall) for (let d = 0; d < 7; d++) if (!W.oncall[d] && nuHave(d, 'N', 'rn')) L.push(['a', `${NU_DN[d]} ${nuFm(nuDof(d))}: אין כוננת לילה`]);
  P.forEach(p => { for (let d = 0; d < 7; d++) { const v = nuBase(nuCell(p.id, d)); if (NU_SH.indexOf(v) >= 0 && nuHit(p.id, d, v)) L.push(['r', `${p.n}: משובצת בחסימה (${NU_DN[d]})`]);
    if (nuSet().noBN && d > 0 && nuBase(nuCell(p.id, d - 1)) === 'N' && (v === 'B' || v === 'E')) L.push(['r', `${p.n}: ${NU_SHN[v]} אחרי לילה (${NU_DN[d]})`]); }
    if (p.prof !== 'stu') { const r = nuQr(p), q = r[1], h = nuWorked(p.id); if (h && q && (h < r[0] || h > r[1])) L.push(['a', `${p.n}: ${h} משמרות, לפי ${p.pct}% צריך ${r[0] === r[1] ? q : r[0] + '–' + r[1]}`]); } });
  return L; }
// the automatic build: the wing's head in the mornings, then nights, evenings and mornings by the minimums; a shift-in-charge in each; the on-call from the qualified
function nuAuto() { const W = nuW(), P = nuStf(); W.grid = {}; W.oncall = {};
  const H = P.find(p => nuCan(p, 'אחראית אגף') && !p.leave); if (H) for (let d = 0; d < 5; d++) if (!nuVacOn(H.id, d) && !nuHit(H.id, d, 'B')) nuPut(H.id, d, 'B*');
  const ok = (p, d, s) => { if (nuCell(p.id, d)) return 0; if (nuWorked(p.id) >= nuQuota(p)) return 0; if (nuHit(p.id, d, s)) return 0;
    if (nuSet().noBN) { if (d > 0 && nuBase(nuCell(p.id, d - 1)) === 'N' && s !== 'N') return 0; if (s === 'N' && d < 6 && nuCell(p.id, d + 1) && nuBase(nuCell(p.id, d + 1)) !== 'N') return 0; } return 1; };
  const sc = (p, d, s) => { let x = nuWorked(p.id) / Math.max(1, nuQuota(p)) * 10; if (nuWe(d)) for (let i = 5; i < 7; i++) if (NU_SH.indexOf(nuBase(nuCell(p.id, i))) >= 0) x += 6; if (s !== 'B' && nuCan(p, 'אחראית אגף')) x += 50; return x + Math.random() * 2; };
  const inCh = (d, s) => P.some(p => nuCell(p.id, d) === s + '*');
  ['N', 'E', 'B'].forEach(s => { for (let d = 0; d < 7; d++) ['rn', 'aid', 'stu'].forEach(g => { let h = nuHave(d, s, g); const n = nuNeed(d, s, g);
    while (h < n) { const c = P.filter(p => p.prof === g && ok(p, d, s)).sort((a, b) => sc(a, d, s) - sc(b, d, s)); let pick = c[0];
      if (g === 'rn' && !inCh(d, s)) { const r = c.find(p => nuCan(p, 'אחראית משמרת')); if (r) pick = r; }
