    NU.t[part] = 0; return NU.api('ops_nsSave', w, part, val, ws).then(r => { if (!NU.d || NU.d.w !== w) return;
      if (part === 'wk' && NU.ws === ws) { NU.d.wk.req = r.req; NU.d.wk.swaps = r.swaps; NU.d.wk.pubAt = r.pubAt; }
