function nuFlow() { const ph = nuW().phase, S = nuSet(), st = [['open', '1 · בקשות פתוחות', `נפתח ${S.open} · נסגר ${S.close}`], ['closed', '2 · נסגר', `עד ${S.blocks} חסימות לכל אחת`], ['draft', '3 · טיוטה', 'בנייה ותיקונים'], ['pub', '4 · פורסם', 'החלפות דרך האפליקציה']];
